import{_ as o,l as m,o as e,c as n,v as t,p as l,x as i,d as s,i as p,S as g}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"PaliGemma","description":"","frontmatter":{"title":"PaliGemma","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/paligemma.md","filePath":"llm/paligemma.md","lastUpdated":1789023840000}'),d={name:"llm/paligemma.md"};function P(h,a,B,c,S,E){const r=m("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="paligemma" tabindex="-1">PaliGemma <a class="header-anchor" href="#paligemma" aria-label="Permalink to &quot;PaliGemma&quot;">​</a></h1><div class="epigraph"><p>目标不是开箱即用的聊天，而是一个会迁移的 3B 基座：前缀里图与问题互相看见，后缀才自回归。</p><footer>—— Beyer 等，PaliGemma: A versatile 3B VLM for transfer，arXiv:2407.07726</footer></div><p>Google 的 PaliGemma 把 PaLI-3 配方落到开源组件上：视觉编码器是对比学习过的 <strong>SigLIP-So400m</strong>（约 400M，「shape optimized」ViT），语言模型是 <strong>Gemma-2B</strong> v1.0 预训练检查点，合计不到 3B。名字里的 Pali 来自 Pathway Language and Image。它在约 40 项任务上迁移，含常规 VLM 基准以及遥感、分割等偏科。与同期「对齐完就能聊」的开源 VLM 不同，Stage1/2 刻意堆<strong>技能密度</strong>，基座不必对用户友好；好用发生在 Stage3 的全参迁移。本篇按原文写 Prefix-LM 掩码、三阶段课程与位置词表，不把后来的 PaliGemma 2（Gemma 2 骨干，arXiv:2412.03555）倒填进来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PaLI 系列已经表明：在宽任务上，小视觉编码器加中等语言模型可以追上更大得多的 PaLI-X / PaLM-E。开源侧缺的是同样可迁移的公开权重：SigLIP 与 Gemma 都已单独发布，缺一份把它们接到一起、并且<strong>为迁移而预训练</strong>的配方。多数 VLM 把第一阶段写成「冻视觉塔、只对齐投影」，再在指令数据上聊起来；这对基准友好，却未必给检测、分割、读小字、多图留下技能。PaliGemma 要的是：几乎 40 个<strong>预训练没见过</strong>的下游任务，用统一、超参很少的微调就能上去，包括把框画进输入、吃 16 帧短视频、NLVR2 这种必须看两张图的题。</p><p>分辨率是另一条约束。224 方图只有 256 个视觉 token，图表与小物体不够；直接训 896 又贵。需要分阶段升分辨率，并且证明哪些任务真正吃分辨率，而不是所有基准都加像素。</p><h3 id="前缀全可见-后缀才因果" tabindex="-1">前缀全可见，后缀才因果 <a class="header-anchor" href="#前缀全可见-后缀才因果" aria-label="Permalink to &quot;前缀全可见，后缀才因果&quot;">​</a></h3><p>输入是一张或多张图加任务文本（prefix），输出是字符串（suffix）。图一律缩成固定方图：224 / 448 / 896，对应 256 / 1024 / 4096 个图像 token，放在序列最前，无需额外位置标记。BOS 开文本，<code>\\n</code> 作为单独分词的 SEP，避免和前后合并。对图像 + 前缀做<strong>双向</strong>注意力，后缀（含 PAD）才自回归。图像 token 因此能「看见」问题，按任务改写表示。消融显示：若把因果掩码扩到前缀甚至图像，迁移变差。这与标准 GPT 式「从头因果」不同，也与仅在图像侧双向的做法不同。</p><p><span class="marginnote">Gemma 词表外加 1024 个坐标 token（归一化坐标分箱）和 128 个分割码字。检测、指向、分割都走同一套离散位置语言，而不是外挂检测头。框也可以画进输入图里当条件（WidgetCap 一类）。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>连接很简单：SigLIP 出 soft token，线性层映到 Gemma 隐维，与文本拼接。训练却分四段叙事里的三阶段（外加单模态已在组件上完成）：</p><h3 id="stage1-广技能-stage2-升分辨率" tabindex="-1">Stage1 广技能，Stage2 升分辨率 <a class="header-anchor" href="#stage1-广技能-stage2-升分辨率" aria-label="Permalink to &quot;Stage1 广技能，Stage2 升分辨率&quot;">​</a></h3><p>Stage1：整模在大规模视觉–语言任务混合上训，<strong>不冻</strong>图像编码器。为避免未对齐语言模型毁掉 SigLIP，视觉塔用更慢的线性 warmup。分辨率 224，文本长 128，共约 <strong>10 亿</strong>样本。任务带独特前缀以免技能互相打架。预训练图会去掉与下游评测近重复的图像。Stage2：同一混合，把需高分辨率的任务（OCR、检测、分割）上采样，分辨率先 448（再约 5000 万样本）后 896（再约 1000 万），文本长加到 512，例如「按阅读顺序读出全部文字」「标出所有已标注物体」。Stage3：全参迁移到单个学术基准，或一份 mix 检查点同时迁到任务子集并加详细字幕与长问答。超参几乎只有学习率、分辨率、训练步数等少数几个；建议值对多数任务已经够用。多图 / 视频：每张图独立编码再拼接，无特殊分隔；16×224 与单张 896 一样是 4096 个图像 token。</p>',13)),(e(),l(g,null,{default:i(()=>[p(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20LR%0A%20%20IMG%5B%22%E6%96%B9%E5%9B%BE%20224%20%2F%20448%20%2F%20896%22%5D%20--%3E%20SIG%5B%22SigLIP-So400m%22%5D%0A%20%20SIG%20--%3E%20LIN%5B%22%E7%BA%BF%E6%80%A7%E6%8A%95%E5%BD%B1%22%5D%0A%20%20LIN%20--%3E%20PRE%5B%22%E5%9B%BE%E5%83%8F%20%2B%20%E5%89%8D%E7%BC%80%20%E5%8F%8C%E5%90%91%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%0A%20%20TXT%5B%22%E4%BB%BB%E5%8A%A1%E5%89%8D%E7%BC%80%22%5D%20--%3E%20PRE%0A%20%20PRE%20--%3E%20SUF%5B%22%E5%90%8E%E7%BC%80%E8%87%AA%E5%9B%9E%E5%BD%92%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>学习率在 Stage1–2 用一条不归零的 rsqrt「无限」日程，阶段之间不断档；迁移再当 cooldown，余弦退火到零。相对常见做法，他们拒绝「先冻视觉塔」：CapPa / LocCa 表明字幕与定位类任务能给对比编码器补上空间关系，而这正是 CLIP/SigLIP 缺的。</p><p><span class="marginnote">Mix 检查点「朝指令调」走近了一步，但原文明确说它还不是 instruction / chat tuning。不要把 Kaggle 上的 mix 权重当成 Gemini 式对话模型。PaliGemma 2 换 Gemma 2、改分辨率档，是另一篇报告。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>「为迁移而预训练」把监督信号从「用户爱看的答法」换成「强迫模型练习的技能」。独特任务前缀让对比、字幕、OCR、检测共存而不互相覆盖；迁移时模型只需认出该用哪项技能，再改输出句法。这解释为何 Stage1 即使缩短 10–30 倍，热门基准仍能看，但作者仍坚持吃满 10 亿样本：要的是概念、文化、语言覆盖，不是把 COCO Captions 刷高。跳过 Stage1 直接迁移明显更差。</p><p>Prefix-LM 让视觉表示成为<strong>条件于问题的</strong>计算，而不是与问题无关的冻结前缀。小模型尤其需要这种容量：2B 语言骨干没有 70B 的世界知识冗余，必须让每一个图像 token 都参与「这道题要看哪」。升分辨率不是免费午餐：表 1 里高亮的读字与小物体任务吃 448/896，分类与粗 VQA 往往 224 已够；16 帧短视频与 896 单图抢同一 token 预算，选哪边是任务问题。</p><h3 id="开箱分数不是这张成绩单的读法" tabindex="-1">开箱分数不是这张成绩单的读法 <a class="header-anchor" href="#开箱分数不是这张成绩单的读法" aria-label="Permalink to &quot;开箱分数不是这张成绩单的读法&quot;">​</a></h3><p>基座在预训练后「不好使」，是设计而不是缺陷。评测协议是：下游任务不出现在预训练混合中，验证集（或从训练划出的 minival）上选超参，再在全训练+验证上重训报测试。数据增强几乎没有，只把图缩成方图——包括 RefCOCO 分割。读论文应看迁移后的约 40 项，而不是零样本聊天印象。作者还跑了掩码方式、Stage1 时长、是否冻视觉塔等消融；Prefix-LM 与不冻视觉塔是两条反复加分的选择。</p><p><span class="marginnote">线性连接器没有 Q-Former 压缩：224 就是 256 token，896 就是 4096。上下文账单随分辨率二次涨（边长加倍、token 乘四）。部署 896 档要按 4k 视觉前缀加文本来配 KV，不能按 Gemma-2B 纯文本 8k 的经验套。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>PaliGemma 不是通用聊天模型，也不是动态分辨率模型：非方图被拉伸，版式任务要自备 letterbox 策略。坐标 1024 箱限制定位精度。分割是码字序列，不是像素级解码器。多图只是拼接，没有 InternVL 式切块或 Qwen 式原生 patch。Gemma 2B 的数学推理弱于 7B/70B，视觉数学不要期望 PaLI-3 论文里更大语言模型的数字。</p><p>预训练数据细节、混合权重以论文附录为准；去掉评测近重复提高了「真迁移」可信度，也使分数不能和未去重的模型直接比。许可走 Gemma 条款，商业使用读模型卡。PaliGemma 2 与后续 Gemma 3 多模态是不同检查点。不要把 Vertex AI 上的托管服务默认值写成论文超参。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PaliGemma 用 SigLIP-So400m + Gemma-2B 做成不到 3B、面向迁移的开源 VLM。</li><li>Prefix-LM：图像与问题双向，答案因果；1024 坐标词 + 128 分割码字承担定位。</li><li>Stage1 广技能、Stage2 升分辨率、Stage3 全参迁移；基座不必开箱好用。</li><li>出处：Beyer 等，<em>PaliGemma: A versatile 3B VLM for transfer</em>，arXiv:2407.07726，2024。对照 PaLI-3、SigLIP 与 Gemma 技术报告。</li></ul>',13))])}const L=o(d,[["render",P]]);export{u as __pageData,L as default};
